117	            CommandResult::error(tr(app.ui_locale, MessageId::CmdPluginBundleUsage))
118	        }
119	        ["update", selector] => update_bundle(app, selector),
120	        ["uninstall", selector] => uninstall_bundle(app, selector),
121	        ["trust", selector] => review_bundle(app, selector),
122	        ["trust", selector, token] => mutate_bundle(app, selector, Mutation::Trust(token)),
123	        ["enable", selector] => mutate_bundle(app, selector, Mutation::Enable),
124	        ["disable", selector] => mutate_bundle(app, selector, Mutation::Disable),
125	        ["revoke", selector] => mutate_bundle(app, selector, Mutation::Revoke),
126	        ["reload"] => {
127	            app.plugin_registry = app.plugin_registry.rediscover_for_workspace(&app.workspace);
128	            app.refresh_skill_cache();
129	            let count = app.plugin_registry.len();
130	            CommandResult::with_message_and_action(
131	                tr(app.ui_locale, MessageId::CmdPluginBundleReloaded)
132	                    .replace("{count}", &count.to_string())
133	                    .replace("{workspace}", &app.workspace.display().to_string()),
134	                AppAction::PluginRegistryChanged,
135	            )
136	        }
137	        ["tools"] => legacy_tools(app, None),
138	        ["tools", name] => legacy_tools(app, Some(name)),
139	        [selector] => {
140	            if app.plugin_registry.get(selector).is_some() {
141	                show_bundle(app, selector)
142	            } else {
143	                // Preserve `/plugin <script-tool>` compatibility while making
144	                // its distinct execution model explicit in the output.
145	                legacy_tools(app, Some(selector))
146	            }
147	        }
148	        _ => CommandResult::error(tr(app.ui_locale, MessageId::CmdPluginBundleUsage)),
149	    }
150	}
